class Solution {
public:
    int equalPairs(vector<vector<int>>& grid) {
        int n = grid.size(), count = 0;
        map<vector<int>, int> rows;
        for (int r = 0; r < n; r++) rows[grid[r]]++;
        for (int c = 0; c < n; c++) {
            vector<int> col;
            for (int r = 0; r < n; r++) col.push_back(grid[r][c]);
            if (rows.count(col)) count += rows[col];
        }
        return count;
    }
};
